//! Faithful pure-Rust port of the mapbox earcut polygon triangulation
//! library (earcut.hpp v2.x), using an arena of nodes with index links
//! instead of raw pointers. Indices type is u32.

pub type Point = [f64; 2];

#[derive(Clone)]
struct Node {
    i: u32,
    x: f64,
    y: f64,
    z: i32,
    prev: usize,
    next: usize,
    prev_z: Option<usize>,
    next_z: Option<usize>,
    steiner: bool,
}

fn area(a: &Node, b: &Node, c: &Node) -> f64 {
    (b.y - a.y) * (c.x - b.x) - (b.x - a.x) * (c.y - b.y)
}

fn sign(val: f64) -> i32 {
    (0.0 < val) as i32 - (val < 0.0) as i32
}

fn point_in_triangle(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64, px: f64, py: f64) -> bool {
    (cx - px) * (ay - py) >= (ax - px) * (cy - py)
        && (ax - px) * (by - py) >= (bx - px) * (ay - py)
        && (bx - px) * (cy - py) >= (cx - px) * (by - py)
}

fn on_segment(p: &Node, q: &Node, r: &Node) -> bool {
    q.x <= p.x.max(r.x) && q.x >= p.x.min(r.x) && q.y <= p.y.max(r.y) && q.y >= p.y.min(r.y)
}

pub struct Earcut {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    vertices_index: u32,
    inv_size: f64,
    min_x: f64,
    min_y: f64,
}

impl Earcut {
    pub fn new() -> Self {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices_index: 0,
            inv_size: 0.0,
            min_x: 0.0,
            min_y: 0.0,
        }
    }

    fn create_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        let idx = self.nodes.len();
        self.nodes.push(Node {
            i,
            x,
            y,
            z: 0,
            prev: idx,
            next: idx,
            prev_z: None,
            next_z: None,
            steiner: false,
        });
        idx
    }

    fn insert_node(&mut self, i: u32, x: f64, y: f64, last: Option<usize>) -> usize {
        let p = self.create_node(i, x, y);
        match last {
            None => {
                self.nodes[p].prev = p;
                self.nodes[p].next = p;
            }
            Some(last) => {
                let last_next = self.nodes[last].next;
                self.nodes[p].next = last_next;
                self.nodes[p].prev = last;
                self.nodes[last_next].prev = p;
                self.nodes[last].next = p;
            }
        }
        p
    }

    fn remove_node(&mut self, p: usize) {
        let next = self.nodes[p].next;
        let prev = self.nodes[p].prev;
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;
        if let Some(pz) = self.nodes[p].prev_z {
            self.nodes[pz].next_z = self.nodes[p].next_z;
        }
        if let Some(nz) = self.nodes[p].next_z {
            self.nodes[nz].prev_z = self.nodes[p].prev_z;
        }
    }

    fn equals(&self, p1: usize, p2: usize) -> bool {
        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    }

    fn node_area(&self, a: usize, b: usize, c: usize) -> f64 {
        area(&self.nodes[a], &self.nodes[b], &self.nodes[c])
    }

    // create a circular doubly linked list from polygon points in the specified winding order
    fn linked_list(&mut self, points: &[Point], clockwise: bool) -> Option<usize> {
        let len = points.len();
        let mut sum = 0.0f64;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        let mut last: Option<usize> = None;
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = Some(self.insert_node(self.vertices_index + i as u32, points[i][0], points[i][1], last));
            }
        } else {
            let mut i = len;
            while i > 0 {
                i -= 1;
                last = Some(self.insert_node(self.vertices_index + i as u32, points[i][0], points[i][1], last));
            }
        }

        if let Some(l) = last {
            let next = self.nodes[l].next;
            if self.equals(l, next) {
                self.remove_node(l);
                last = Some(next);
            }
        }

        self.vertices_index += len as u32;
        last
    }

    // eliminate colinear or duplicate points
    fn filter_points(&mut self, start: Option<usize>, end: Option<usize>) -> Option<usize> {
        let start = start?;
        let mut end = end.unwrap_or(start);
        let mut p = start;
        loop {
            let mut again = false;
            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;
            if !self.nodes[p].steiner
                && (self.equals(p, next) || self.node_area(prev, p, next) == 0.0)
            {
                self.remove_node(p);
                p = self.nodes[p].prev;
                end = p;
                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = next;
            }
            if !(again || p != end) {
                break;
            }
        }
        Some(end)
    }

    // main ear slicing loop which triangulates a polygon (given as a linked list)
    fn earcut_linked(&mut self, ear: Option<usize>, pass: i32) {
        let mut ear = match ear {
            Some(e) => e,
            None => return,
        };

        if pass == 0 && self.inv_size != 0.0 {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.inv_size != 0.0 {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = ear;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(Some(ear), None);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small self-intersections locally
                    let filtered = self.filter_points(Some(ear), None).unwrap();
                    ear = self.cure_local_intersections(filtered);
                    self.earcut_linked(Some(ear), 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }

    // check whether a polygon node forms a valid ear with adjacent nodes
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.node_area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
        let ear_prev = self.nodes[ear].prev;

        // now make sure we don't have other points inside the potential ear
        let mut p = self.nodes[self.nodes[ear].next].next;

        while p != ear_prev {
            let inside = point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[p].x, self.nodes[p].y);
            if inside
                && self.node_area(self.nodes[p].prev, p, self.nodes[p].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if self.node_area(a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox; min & max are calculated like this for speed
        let min_tx = if ax < bx {
            if ax < cx { ax } else { cx }
        } else if bx < cx {
            bx
        } else {
            cx
        };
        let min_ty = if ay < by {
            if ay < cy { ay } else { cy }
        } else if by < cy {
            by
        } else {
            cy
        };
        let max_tx = if ax > bx {
            if ax > cx { ax } else { cx }
        } else if bx > cx {
            bx
        } else {
            cx
        };
        let max_ty = if ay > by {
            if ay > cy { ay } else { cy }
        } else if by > cy {
            by
        } else {
            cy
        };

        // z-order range for the current triangle bbox;
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        let ear_prev = self.nodes[ear].prev;
        let ear_next = self.nodes[ear].next;

        let mut p = self.nodes[ear].prev_z;
        let mut q = self.nodes[ear].next_z;

        // look for points inside the triangle in both directions
        while p.is_some() && self.nodes[p.unwrap()].z >= min_z
            && q.is_some() && self.nodes[q.unwrap()].z <= max_z
        {
            let pu = p.unwrap();
            if pu != ear_prev
                && pu != ear_next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pu].x, self.nodes[pu].y)
                && self.node_area(self.nodes[pu].prev, pu, self.nodes[pu].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pu].prev_z;

            let qu = q.unwrap();
            if qu != ear_prev
                && qu != ear_next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[qu].x, self.nodes[qu].y)
                && self.node_area(self.nodes[qu].prev, qu, self.nodes[qu].next) >= 0.0
            {
                return false;
            }
            q = self.nodes[qu].next_z;
        }

        // look for remaining points in decreasing z-order
        while let Some(pu) = p {
            if self.nodes[pu].z < min_z {
                break;
            }
            if pu != ear_prev
                && pu != ear_next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[pu].x, self.nodes[pu].y)
                && self.node_area(self.nodes[pu].prev, pu, self.nodes[pu].next) >= 0.0
            {
                return false;
            }
            p = self.nodes[pu].prev_z;
        }

        // look for remaining points in increasing z-order
        while let Some(qu) = q {
            if self.nodes[qu].z > max_z {
                break;
            }
            if qu != ear_prev
                && qu != ear_next
                && point_in_triangle(ax, ay, bx, by, cx, cy, self.nodes[qu].x, self.nodes[qu].y)
                && self.node_area(self.nodes[qu].prev, qu, self.nodes[qu].next) >= 0.0
            {
                return false;
            }
            q = self.nodes[qu].next_z;
        }

        true
    }

    // go through all polygon nodes and cure small local self-intersections
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        let mut p = start;
        let mut start = start;
        loop {
            let a = self.nodes[p].prev;
            let b = self.nodes[self.nodes[p].next].next;
            let p_next = self.nodes[p].next;

            if !self.equals(a, b)
                && self.intersects(a, p, p_next, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove two nodes involved
                self.remove_node(p);
                self.remove_node(p_next);

                p = b;
                start = b;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        self.filter_points(Some(p), None).unwrap()
    }

    // try splitting polygon into two and triangulate them independently
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    let c_next = self.nodes[c].next;
                    let a = self.filter_points(Some(a), Some(a_next)).unwrap();
                    let c = self.filter_points(Some(c), Some(c_next)).unwrap();

                    // run earcut on each half
                    self.earcut_linked(Some(a), 0);
                    self.earcut_linked(Some(c), 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    // link every hole into the outer loop, producing a single-ring polygon without holes
    fn eliminate_holes(&mut self, points: &[Vec<Point>], outer_node: usize) -> usize {
        let len = points.len();

        let mut queue: Vec<usize> = Vec::new();
        for i in 1..len {
            if let Some(list) = self.linked_list(&points[i], false) {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        let nodes = &self.nodes;
        queue.sort_by(|&a, &b| nodes[a].x.partial_cmp(&nodes[b].x).unwrap());

        // process holes from left to right
        let mut outer_node = outer_node;
        for &hole in &queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }
        outer_node
    }

    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = match self.find_hole_bridge(hole, outer_node) {
            Some(b) => b,
            None => return outer_node,
        };

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let br_next = self.nodes[bridge_reverse].next;
        self.filter_points(Some(bridge_reverse), Some(br_next));
        let on_next = self.nodes[outer_node].next;
        self.filter_points(Some(outer_node), Some(on_next)).unwrap_or(outer_node)
    }

    // David Eberly's algorithm for finding a bridge between hole and outer polygon
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> Option<usize> {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m: Option<usize> = None;

        // find a segment intersected by a ray from the hole's leftmost point to the left;
        // segment's endpoint with lesser x will be potential connection point
        loop {
            let pn = self.nodes[p].next;
            if hy <= self.nodes[p].y
                && hy >= self.nodes[pn].y
                && self.nodes[pn].y != self.nodes[p].y
            {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y) * (self.nodes[pn].x - self.nodes[p].x)
                        / (self.nodes[pn].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    m = Some(if self.nodes[p].x < self.nodes[pn].x { p } else { pn });
                    if x == hx {
                        return m; // hole touches outer segment; pick leftmost endpoint
                    }
                }
            }
            p = pn;
            if p == outer_node {
                break;
            }
        }

        let mut m = m?;

        // look for points inside the triangle of hole point, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the point of the minimum angle with the ray as connection point
        let stop = m;
        let mut tan_min = f64::INFINITY;

        p = self.nodes[m].next;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;

        loop {
            if hx >= self.nodes[p].x
                && self.nodes[p].x >= mx
                && hx != self.nodes[p].x
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    self.nodes[p].x,
                    self.nodes[p].y,
                )
            {
                let tan_cur = (hy - self.nodes[p].y).abs() / (hx - self.nodes[p].x); // tangential

                if self.locally_inside(p, hole)
                    && (tan_cur < tan_min
                        || (tan_cur == tan_min
                            && (self.nodes[p].x > self.nodes[m].x
                                || (self.nodes[p].x == self.nodes[m].x
                                    && self.node_area(self.nodes[p].prev, p, self.nodes[p].next) < 0.0))))
                {
                    m = p;
                    tan_min = tan_cur;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        Some(m)
    }

    // find the leftmost node of a polygon ring
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }

    // check if a diagonal between two polygon nodes is valid (lies in polygon interior)
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;

        self.nodes[a_next].i != self.nodes[b].i
            && self.nodes[a_prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b) // locally visible
                && (self.node_area(a_prev, a, b_prev) != 0.0
                    || self.node_area(a, b_prev, b) != 0.0)) // does not create opposite-facing sectors
                || (self.equals(a, b)
                    && self.node_area(a_prev, a, a_next) > 0.0
                    && self.node_area(b_prev, b, self.nodes[b].next) > 0.0)) // special zero-length case
    }

    // signed area of a triangle
    // check if a polygon diagonal intersects any polygon segments
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let pn = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[pn].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[pn].i != self.nodes[b].i
                && self.intersects(p, pn, a, b)
            {
                return true;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        false
    }

    // check if a polygon diagonal is locally inside the polygon
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let a_prev = self.nodes[a].prev;
        let a_next = self.nodes[a].next;
        if self.node_area(a_prev, a, a_next) < 0.0 {
            self.node_area(a, b, a_next) >= 0.0 && self.node_area(a, a_prev, b) >= 0.0
        } else {
            self.node_area(a, b, a_prev) < 0.0 || self.node_area(a, a_next, b) < 0.0
        }
    }

    // check if the middle point of a polygon diagonal is inside the polygon
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let pn = self.nodes[p].next;
            if ((self.nodes[p].y > py) != (self.nodes[pn].y > py))
                && self.nodes[pn].y != self.nodes[p].y
                && (px
                    < (self.nodes[pn].x - self.nodes[p].x) * (py - self.nodes[p].y)
                        / (self.nodes[pn].y - self.nodes[p].y)
                        + self.nodes[p].x)
            {
                inside = !inside;
            }
            p = pn;
            if p == a {
                break;
            }
        }
        inside
    }

    // link two polygon vertices with a bridge; if the vertices belong to the same ring, it splits polygon into two;
    // if one belongs to the outer ring and another to a hole, it merges it into a single ring
    fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let (ai, ax, ay) = (self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let (bi, bx, by) = (self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let a2 = self.create_node(ai, ax, ay);
        let b2 = self.create_node(bi, bx, by);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    // check if two segments intersect
    fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sign(self.node_area(p1, q1, p2));
        let o2 = sign(self.node_area(p1, q1, q2));

        let o3 = sign(self.node_area(p2, q2, p1));
        let o4 = sign(self.node_area(p2, q2, q1));

        if o1 != o2 && o3 != o4 {
            return true; // general case
        }

        if o1 == 0 && on_segment(&self.nodes[p1], &self.nodes[p2], &self.nodes[q1]) {
            return true; // p1, q1 and p2 are collinear and p2 lies on p1q1
        }
        if o2 == 0 && on_segment(&self.nodes[p1], &self.nodes[q2], &self.nodes[q1]) {
            return true; // p1, q1 and q2 are collinear and q2 lies on p1q1
        }
        if o3 == 0 && on_segment(&self.nodes[p2], &self.nodes[p1], &self.nodes[q2]) {
            return true; // p2, q2 and p1 are collinear and p1 lies on p2q2
        }
        if o4 == 0 && on_segment(&self.nodes[p2], &self.nodes[q1], &self.nodes[q2]) {
            return true; // p2, q2 and q1 are collinear and q1 lies on p2q2
        }

        false
    }

    // interlink polygon nodes in z-order
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nodes[p].z == 0 {
                self.nodes[p].z = self.z_order(self.nodes[p].x, self.nodes[p].y);
            }
            self.nodes[p].prev_z = Some(self.nodes[p].prev);
            self.nodes[p].next_z = Some(self.nodes[p].next);
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        let prev_z = self.nodes[p].prev_z.unwrap();
        self.nodes[prev_z].next_z = None;
        self.nodes[p].prev_z = None;

        self.sort_linked(p);
    }

    // Simon Tatham's linked list merge sort algorithm
    // http://www.chiark.greenend.org.uk/~sgtatham/algorithms/listsort.html
    fn sort_linked(&mut self, list: usize) -> usize {
        let mut in_size: usize = 1;
        let mut list = Some(list);

        loop {
            let mut p = list;
            list = None;
            let mut tail: Option<usize> = None;
            let mut num_merges = 0;

            while let Some(pu) = p {
                num_merges += 1;
                let mut q = Some(pu);
                let mut p_size = 0;
                for _ in 0..in_size {
                    p_size += 1;
                    q = self.nodes[q.unwrap()].next_z;
                    if q.is_none() {
                        break;
                    }
                }

                let mut q_size = in_size;
                let mut pu = pu;

                while p_size > 0 || (q_size > 0 && q.is_some()) {
                    let e: usize;
                    if p_size == 0 {
                        let qu = q.unwrap();
                        e = qu;
                        q = self.nodes[qu].next_z;
                        q_size -= 1;
                    } else if q_size == 0 || q.is_none() {
                        e = pu;
                        p = self.nodes[pu].next_z;
                        pu = p.unwrap_or(pu);
                        p_size -= 1;
                    } else if self.nodes[pu].z <= self.nodes[q.unwrap()].z {
                        e = pu;
                        p = self.nodes[pu].next_z;
                        pu = p.unwrap_or(pu);
                        p_size -= 1;
                    } else {
                        let qu = q.unwrap();
                        e = qu;
                        q = self.nodes[qu].next_z;
                        q_size -= 1;
                    }

                    match tail {
                        Some(t) => self.nodes[t].next_z = Some(e),
                        None => list = Some(e),
                    }

                    self.nodes[e].prev_z = tail;
                    tail = Some(e);
                }

                p = q;
            }

            self.nodes[tail.unwrap()].next_z = None;

            if num_merges <= 1 {
                return list.unwrap();
            }

            in_size *= 2;
        }
    }

    // z-order of a point given coords and size of the data bounding box
    fn z_order(&self, x_: f64, y_: f64) -> i32 {
        // coords are transformed into non-negative 15-bit integer range
        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;

        x = (x | (x << 8)) & 0x00FF00FF;
        x = (x | (x << 4)) & 0x0F0F0F0F;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;

        y = (y | (y << 8)) & 0x00FF00FF;
        y = (y | (y << 4)) & 0x0F0F0F0F;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;

        x | (y << 1)
    }

    pub fn run(&mut self, points: &[Vec<Point>]) {
        self.indices.clear();
        self.nodes.clear();
        self.vertices_index = 0;
        self.inv_size = 0.0;
        self.min_x = 0.0;
        self.min_y = 0.0;

        let len = points.len();
        if len == 0 {
            return;
        }

        // outer ring
        let outer_node = match self.linked_list(&points[0], true) {
            Some(n) => n,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }
        let mut outer_node = outer_node;

        // if the shape is not too simple, we'll use z-order curve hash later; calculate polygon bbox
        if points[0].len() > 80 {
            let mut min_x = points[0][0][0];
            let mut max_x = min_x;
            let mut min_y = points[0][0][1];
            let mut max_y = min_y;
            for i in 1..points[0].len() {
                min_x = min_x.min(points[0][i][0]);
                min_y = min_y.min(points[0][i][1]);
                max_x = max_x.max(points[0][i][0]);
                max_y = max_y.max(points[0][i][1]);
            }
            let inv = (max_x - min_x).max(max_y - min_y);
            self.inv_size = if inv != 0.0 { 32767.0 / inv } else { 0.0 };
            self.min_x = min_x;
            self.min_y = min_y;
        }

        if len > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        self.earcut_linked(Some(outer_node), 0);
    }

    pub fn indices(&self) -> &[u32] {
        &self.indices
    }
}

/// Triangulate the given polygon (first ring = outer, rest = holes).
/// Returns flat indices into the concatenated rings, like mapbox::earcut<uint32_t>.
pub fn earcut(polygon: &[Vec<Point>]) -> Vec<u32> {
    let mut e = Earcut::new();
    e.run(polygon);
    e.indices().to_vec()
}

