#[path = "src/earcut.rs"]
mod earcut;

use std::io::Write;

/// C `atoi` semantics: skip leading whitespace, optional sign, leading digits.
fn c_atoi(s: &str) -> i32 {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }
    let mut sign: i64 = 1;
    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
        if b[i] == b'-' {
            sign = -1;
        }
        i += 1;
    }
    let mut val: i64 = 0;
    while i < b.len() && b[i].is_ascii_digit() {
        val = val.wrapping_mul(10).wrapping_add((b[i] - b'0') as i64);
        i += 1;
    }
    sign.wrapping_mul(val) as i32
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut n: i32 = 10;
    if args.len() > 1 {
        n = c_atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let mut layer: i32 = 0;
    while layer < n {
        let mut ring: Vec<[f64; 2]> = Vec::new();
        let radius = (layer + 1) as f64 * 0.3;
        let count = (layer + 3) * 2;
        let mut i: i32 = 0;
        while i < count {
            let angle = 2.0 * std::f64::consts::PI * i as f64 / count as f64;
            let offset = layer as f64 * 0.1;
            ring.push([
                (radius + offset) * angle.cos(),
                (radius + offset) * angle.sin(),
            ]);
            i += 1;
        }
        polygon.push(ring);
        layer += 1;
    }

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for idx in indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

